"""Extraction of NDVI from Sentinel-2 images (for greenery data) from each year 2016-2023 with GEE"""

# London
london_roi = ee.Geometry.Rectangle([-0.51, 51.28, 0.33, 51.69])

# def function to get NDVI (with near infrared and red bands)
def add_ndvi(image):
    ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI')
    return image.addBands(ndvi)

# load Sentinel-2 dataset
print("Loading Sentinel-2 dataset...")
s2_base = ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED")

# loop through the years
for year in range(2016, 2024):
    # filter for year, location (+ remove more than 20% cloudy data)
    s2_filtered = (s2_base
                   .filterBounds(london_roi)
                   .filter(ee.Filter.calendarRange(year, year, 'year'))
                   .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20))
                   .map(add_ndvi))
    # extract NDVI band, take median
    annual_greenery = s2_filtered.select('NDVI').median()
    file_name = f"Sentinel2_NDVI_London_{year}"
    # def export task
    task = ee.batch.Export.image.toDrive(
        image=annual_greenery,
        description=f"Export_London_Greenery_{year}",
        folder="AI4EO_Big_Project",
        fileNamePrefix=file_name,
        region=london_roi,
        scale=10,          # 10meter resolution
        crs="EPSG:4326",
        maxPixels=1e13     # safety buffer
    )

    task.start()
    print(f"Started export task for {year}...")

# output
print("Complete!")

