"""That is too many unmatched wards. It is probably becuase three boroughs had their wards completely redrawn in 2014 (we use the new ones after 2014), while the financial data also has data from before 2014. We don't really want to lose that data.

However there is a small issue. Since some of the boroughs were redrawn, while the financial statistics describe the old footprint, what we are doing is just approximating them since the stats and geometry might mismatch a bit.
"""

unmatched = wards_fin[wards_fin["New code"].isna()]
print(unmatched["BOROUGH"].value_counts())

def norm(s):
    s = str(s).lower().replace("&", "and")
    s = re.sub(r"[^a-z0-9]+", " ", s).strip()
    return re.sub(r"\s+", " ", s)

# financial rows keyed by normalized "Borough - Ward" name
fin_named = fin.drop_duplicates("New code").copy()
fin_named["key"] = fin_named["Ward name"].map(norm)
fin_named = fin_named.drop_duplicates("key").set_index("key")

# rebuild the join + a matching name key on the boundary side
wf = wards.merge(fin.drop_duplicates("New code"),
                 left_on="GSS_CODE", right_on="New code", how="left")
wf["key"] = (wf["BOROUGH"] + " - " + wf["NAME"]).map(norm)

# recover the code-unmatched rows via the name key
fin_cols = list(fin.columns)
recovered = 0
for i in wf.index[wf["New code"].isna()]:
    k = wf.at[i, "key"]
    if k in fin_named.index:
        for c in fin_cols:
            wf.at[i, c] = fin_named.at[k, c]
        recovered += 1

print("Recovered via name:", recovered)
print("Still unmatched:", wf["New code"].isna().sum())

# reproject + overwrite the saved master frame
wf = wf.to_crs("EPSG:4326")
wf.to_file(os.path.join(root, "wards_with_financial.geojson"), driver="GeoJSON")

