fin_features = ["Median Household income estimate (2012/13)", "Median House Price (£) - 2014"]

# strip £, commas, spaces -> numeric
def to_num(s):
    return pd.to_numeric(s.astype(str).str.replace(r"[^0-9.\-]", "", regex=True),
                         errors="coerce")

wf["fin_imputed"] = wf["New code"].isna()   # flag approximate wards

for col in fin_features:
    wf[col] = to_num(wf[col])
    wf[col] = wf.groupby("BOROUGH")[col].transform(lambda s: s.fillna(s.mean()))
    wf[col] = wf[col].fillna(wf[col].mean())   # safety net if a borough is missing

print("Imputed wards:", int(wf["fin_imputed"].sum()))
print(wf[fin_features].isna().sum())

