def add_zonal(gdf, pattern, prefix):
    for path in sorted(glob.glob(os.path.join(root, pattern))):
        year = re.search(r"(\d{4})", os.path.basename(path)).group(1)
        gdf[f"{prefix}_{year}"] = [s["mean"] for s in zonal_stats(gdf, path, stats=["mean"])]
        print(f"{prefix}_{year} done")
    return gdf

wards = add_zonal(wards, "VIIRS_London_*.tif", "viirs")
wards = add_zonal(wards, "Sentinel2_NDVI_London_*.tif", "ndvi")

