buildings = (ee.FeatureCollection(tiles[0])
             .merge(ee.FeatureCollection(tiles[1]))
             .filterBounds(london_roi)
             .filter(ee.Filter.notNull(["height"])))

def prep(f):
    a = f.geometry().area(1)                       # geodesic footprint area, m²
    h = ee.Number(f.get("height"))
    c = f.geometry().centroid(1).coordinates()     # one point per building
    return ee.Feature(None, {
        "lon": c.get(0), "lat": c.get(1),
        "height": h, "area": a, "vol": a.multiply(h)   # m³ per building
    })

points = buildings.map(prep)

task = ee.batch.Export.table.toDrive(
    collection=points,
    description="Export_London_BuildingPoints",
    folder="AI4EO_Big_Project",
    fileNamePrefix="building_points",
    fileFormat="CSV",
    selectors=["lon", "lat", "height", "area", "vol"]
)
