"""#Linear Regression based on three pillars: building volume, NDVI mean and Income"""

wards = gpd.read_file(os.path.join(root, "wards_with_financial.geojson"))
income_col = "Median Household income estimate (2012/13)"

d = wards.copy()
d["log_viirs"]  = np.log(d["viirs_mean"])
d["log_volume"] = np.log(d["bld_volume"])
d[income_col]   = pd.to_numeric(d[income_col], errors="coerce")

features = ["log_volume", "ndvi_mean", income_col]
d = d.dropna(subset=features + ["log_viirs"]).copy()
print("wards in model:", len(d))

# standardize predictors
Xr = d[features]
Xs = (Xr - Xr.mean()) / Xr.std()
Xs.columns = ["building_volume", "greenery", "wealth"]
Xc = sm.add_constant(Xs)

# are the three pillars actually distinct?
vif = pd.Series([variance_inflation_factor(Xc.values, i) for i in range(1, Xc.shape[1])],
                index=Xs.columns, name="VIF")
print("\nVIF (want < 5):\n", vif.round(2))

# fit
y = d["log_viirs"]
model = sm.OLS(y, Xc).fit(cov_type="HC3")
print(model.summary())

# residuals
d["pred"]     = model.predict(Xc)
d["residual"] = y - d["pred"]
d["resid_z"]  = (d["residual"] - d["residual"].mean()) / d["residual"].std()

wards = wards.merge(d[["GSS_CODE","pred","residual","resid_z"]], on="GSS_CODE", how="left")
wards.to_file(os.path.join(root, "wards_with_financial.geojson"), driver="GeoJSON")

flag = "fin_imputed"
print("\n--- MOST OVER-LIT (brighter than their buildings/greenery/wealth predict) ---")
print(d.nlargest(8, "residual")[["NAME","BOROUGH","residual",flag]].to_string(index=False))
print("\n--- MOST UNDER-LIT (darker than predicted) ---")
print(d.nsmallest(8, "residual")[["NAME","BOROUGH","residual",flag]].to_string(index=False))

"""# Random Forest model

## Preprocessing

Calculate the mean NDVI and VIIRS values for all wards across 8 years and put it into a csv with GEE.

This is necessary to have both financial data and the earlier pixel-by-pixel data as ward-by-ward data.
"""

root  = "/content/drive/MyDrive/AI4EO_Big_Project"
# reshape geojson to shape file, so it can be uploaded (to bypass upload limitations)
geojson_path = os.path.join(f"{root}/AI4EO_Big_Project", "wards_with_financial.geojson")
shp_dir = os.path.join(f"{root}/AI4EO_Big_Project", "wards_shapefile")
shp_path = os.path.join(shp_dir, "wards.shp")
os.makedirs(shp_dir, exist_ok=True)
# load and convert the file
gdf = gpd.read_file(geojson_path)
gdf.to_file(shp_path)
# output
print("Conversion to Shapefile complete.")

"""I cannot run the cell below because you put it in a private project that I don't have access to in GEE - Mateusz :(

  Fixed! - Dóri:)
"""

# load data directly from google cloud servers
wards_fc = ee.FeatureCollection("projects/ai4eo-big-project/assets/wards_shapefile-20260710T162250Z-2-001")

# function to filter out clouds from Sentinel-2 images
def mask_s2_clouds(image):
  qa = image.select('QA60')
  cloud_bit_mask = 1 << 10
  cirrus_bit_mask = 1 << 11
  mask = qa.bitwiseAnd(cloud_bit_mask).eq(0).And(qa.bitwiseAnd(cirrus_bit_mask).eq(0))
  return image.updateMask(mask)

# extract VIIRS and Sentinel-2 data again, but into a csv dataframe (for easier handling)
all_years_data = []
for year in range(2016, 2024):
  print(f"Processing {year}...")

  # VIIRS
  # extract the data for each year and reduce them to sigle annual averages
  viirs_annual = ee.ImageCollection("NOAA/VIIRS/DNB/MONTHLY_V1/VCMSLCFG") \
                  .filterDate(f'{year}-01-01', f'{year}-12-31') \
                  .select('avg_rad') \
                  .reduce(ee.Reducer.mean())
  # calculate the mean light for every ward polygon -> FeatureCollection containing the wards and their light scores
  ward_lights = viirs_annual.reduceRegions(
      collection = wards_fc,
      reducer = ee.Reducer.mean(),
      scale = 500,
      tileScale = 4
  )
  # keep only the necessary data (would be too big otherwise)
  ward_lights_table = ward_lights.map(lambda f: ee.Feature(None, f.toDictionary(['GSS_CODE', 'mean'])))
  # convert the cloud result back into a Pandas DataFrame and change column labels
  df_viirs = geemap.ee_to_df(ward_lights_table).rename(columns={'mean': 'VIIRS_Mean_Dynamic'})

  # Sentinel-2
  # extract data, mask clouds (in the relevant months)
  s2_collection = ee.ImageCollection("COPERNICUS/S2_SR_HARMONIZED") \
                    .filterDate(f'{year}-05-01', f'{year}-09-30') \
                    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) \
                    .map(mask_s2_clouds)
  # NDVI calc with normalized difference formula: (NIR - Red) / (NIR + Red)
  def calculate_ndvi(img):
    return img.normalizedDifference(['B8', 'B4']).rename('NDVI')
  ndvi_annual = s2_collection.map(calculate_ndvi).reduce(ee.Reducer.mean())
  # calculate the mean ndvi for every ward polygon -> FeatureCollection containing the wards and their light scores
  ward_ndvi = ndvi_annual.reduceRegions(
      collection = wards_fc,
      reducer = ee.Reducer.mean(),
      scale = 10,
      tileScale = 16
  )
  # clean again and convert back
  ward_ndvi_table = ward_ndvi.map(lambda f: ee.Feature(None, f.toDictionary(['GSS_CODE', 'mean'])))
  df_ndvi = geemap.ee_to_df(ward_ndvi_table).rename(columns={'mean': 'NDVI_Mean_Dynamic'})

  # JOIN
  # join satellites for each year (by ward ID)
  df_year = pd.merge(df_viirs, df_ndvi, on='GSS_CODE')
  df_year['Year'] = year
  # gather in list
  all_years_data.append(df_year)

# gather into long-format panel data
final_timeline_df = pd.concat(all_years_data, ignore_index=True)
# create new file for it
output_path = os.path.join(f"{root}/AI4EO_Big_Project", "ward_timeline_data_2016_2023.parquet") # here I accidentally put it in the wrong folder before, but I added it manually (and rewrote the code correctly in case we need to rerun it)
final_timeline_df.to_parquet(output_path, index=False)

