"""# Multi-layer Perceptron regressor (MLP)

In this part I will try to also implement an MLP to add more *breadth*
"""

df = pd.read_parquet(os.path.join(root, "final_ml_panel_dataset.parquet")).dropna(
    subset=['VIIRS_Mean_Dynamic', 'NDVI_Mean_Dynamic',
            'Median Household income estimate (2012/13)', 'bld_volume'])
feature_cols = ['Median Household income estimate (2012/13)',
                'NDVI_Mean_Dynamic', 'bld_volume']

train, test = df[df['Year'] <= 2021], df[df['Year'] >= 2022]
X_train, X_test = train[feature_cols], test[feature_cols]
y_train, y_test = np.log1p(train['VIIRS_Mean_Dynamic']), np.log1p(test['VIIRS_Mean_Dynamic'])

# We need to scale the variables, otherwise the net will only percieve income
Xtr = X_train.copy()
Xte = X_test.copy()
Xtr['bld_volume'] = np.log1p(Xtr['bld_volume'])
Xte['bld_volume'] = np.log1p(Xte['bld_volume'])
Xtr['Median Household income estimate (2012/13)'] = np.log1p(Xtr['Median Household income estimate (2012/13)'])
Xte['Median Household income estimate (2012/13)'] = np.log1p(Xte['Median Household income estimate (2012/13)'])

sc = StandardScaler()
Xtr_s = sc.fit_transform(Xtr)
Xte_s = sc.transform(Xte)

# train
def mlp():
    return MLPRegressor(hidden_layer_sizes=(64, 32), activation='relu',
                        solver='adam', learning_rate_init=1e-3, alpha=1e-3,
                        max_iter=4000, early_stopping=False,
                        n_iter_no_change=50, tol=1e-6, random_state=42)

m = mlp().fit(sc.fit_transform(Xtr[feature_cols]), y_train)
pred = m.predict(sc.transform(Xte[feature_cols]))

print("--- MLP (adam, test 2022–23, log scale) ---")
print(f"R²  : {r2_score(y_test, pred):.4f}")
print(f"MAE : {mean_absolute_error(y_test, pred):.4f}")
print(f"RMSE: {np.sqrt(mean_squared_error(y_test, pred)):.4f}")

# ablation: retrain with each feature removed -> R² drop
print("\n--- Ablation (R² when feature removed) ---")
full_r2 = r2_score(y_test, pred)
for drop in feature_cols:
    keep = [c for c in feature_cols if c != drop]
    s2 = StandardScaler()
    m2 =  mlp().fit(s2.fit_transform(Xtr[keep]), y_train)
    r2_wo = r2_score(y_test, m2.predict(s2.transform(Xte[keep])))
    print(f"without {drop[:45]:<45} R² = {r2_wo:.4f}  (Δ {full_r2 - r2_wo:+.4f})")

"""In Ablation part it shows us how much accuracy we lose if we drop one of those features. Showing that it's predicting better with them rather than without.

Our accuracy is as good as our linear reg. RF still wins big.
"""

mlp_test = test.copy()
mlp_test["Predicted_Radiance"] = np.expm1(m.predict(sc.transform(Xte[feature_cols])))
mlp_test["Actual_Radiance"]    = np.expm1(np.log1p(mlp_test["VIIRS_Mean_Dynamic"]))
mlp_test["Residual"]           = mlp_test["Actual_Radiance"] - mlp_test["Predicted_Radiance"]

mlp_2023 = mlp_test[mlp_test["Year"] == 2023][["GSS_CODE", "Residual"]]

# ward geo
root_geo = "/content/drive/MyDrive/AI4EO_Big_Project"
map_gdf = gpd.read_file(os.path.join(root_geo, "wards_with_financial.geojson"))[
    ["GSS_CODE", "NAME", "BOROUGH", "geometry"]].to_crs(27700)
mlp_map = map_gdf.merge(mlp_2023, on="GSS_CODE", how="inner")

div_norm = mcolors.TwoSlopeNorm(vmin=mlp_map["Residual"].min(),
                                vcenter=0.,
                                vmax=mlp_map["Residual"].max())

