# legend to layer
class BindColormap(MacroElement):
    def __init__(self, layer, colormap, show=False):
        super().__init__(); self.layer, self.colormap = layer, colormap
        self.initial = "block" if show else "none"
        self._template = Template("""
        {% macro script(this, kwargs) %}
            {{this.colormap.get_name()}}.svg[0][0].style.display = '{{this.initial}}';
            {{this._parent.get_name()}}.on('overlayadd', function (e) {
                if (e.layer == {{this.layer.get_name()}}) {{this.colormap.get_name()}}.svg[0][0].style.display='block';});
            {{this._parent.get_name()}}.on('overlayremove', function (e) {
                if (e.layer == {{this.layer.get_name()}}) {{this.colormap.get_name()}}.svg[0][0].style.display='none';});
        {% endmacro %}""")

# build
minx, miny, maxx, maxy = w.total_bounds
m = folium.Map(location=[(miny+maxy)/2, (minx+maxx)/2], zoom_start=10, tiles="CartoDB positron")

