def mpl_cmap(name, vmin, vmax, caption, n=256):
    cols = [mcolors.to_hex(mcm.get_cmap(name)(i/(n-1))) for i in range(n)]
    c = cm.LinearColormap(cols, vmin=float(vmin), vmax=float(vmax)); c.caption = caption
    return c

